with lines as (select id, service, level, key, value from app_logs lateral view outer explode(context) e as key, value), valid as (select *, trim(key) clean_key from lines where key is distinct from 'version'), matched_keys as (select level, service from valid except select level, service from app_logs where level = 'DEBUG'), kept_rows as (select s.* from valid s join matched_keys k on s.level = k.level and s.service = k.service), cleaned as (select *, substring(key, 1, 2) key_prefix, upper(key) key_upper, coalesce(key, 'UNKNOWN') key_filled from kept_rows where level = 'DEBUG'), matched_keys_2 as (select level from cleaned intersect select level from app_logs where host = 'h1'), reconciled as (select s.* from cleaned s join matched_keys_2 k on s.level = k.level) select id, service, key, clean_key, key_prefix, key_upper, key_filled from reconciled
